questionvariables.text:
/* Design backwards from f'(x) = m x + k. */
m : rand([-2,-1,1,2]);              /* slope of f' = 2a; |m|<=2 keeps a true 1:1 board a sensible size */
a : m/2;                            /* leading coefficient of f (whole or half integer) */
/* intercept k = b. Vertex x = -k/m must be an INTEGER, so m must divide k: any k when
   |m|=1, but only even k when |m|=2. */
kpool : if abs(m) = 1 then [-3,-2,-1,0,1,2,3] else [-2,0,2];
k : rand(kpool);
/* vertical shift c in -2..2, excluding two values: c = k (so the "used c" distractor stays
   distinct from the correct intercept) and c = k^2/(2*m) (which would put the vertex ON the
   x-axis, y_vertex = 0, collapsing the "line through the vertex" diagnostic). */
c : rand(delete(k^2/(2*m), delete(k, [-2,-1,0,1,2])));

fexpr : a*x^2 + k*x + c;            /* f(x), for display */

/* Board: square [-8,8]^2 with keepAspectRatio TRUE, so a slope looks like that slope.
   Vertex x = -k/m is always an integer (k chosen so m divides k), giving a clean
   horizontal-tangent point to sample and place. */
win     : 8;                        /* half-window (square window [-8,8] x [-8,8]) */
/* Restrict the slider so A = (x, f(x)) stays on the board: |f(x)| <= win. The parabola
   reaches the near board edge (top if it opens up, bottom if it opens down) at the
   vertex +/- halfw, so slide x over [vertex - halfw, vertex + halfw]. */
xslider_mid  : -k/m;                          /* vertex x: start A at the horizontal tangent */
yvertex      : c - k^2/(4*a);                 /* vertex y */
xedge_bound  : if a > 0 then win else -win;   /* the board edge the arms reach */
xslider_dist : sqrt((xedge_bound - yvertex)/a) - 0.15;  /* half-width of {|f(x)| <= win}, inset slightly */
yinit   : 3;                        /* starting height of the (wrong) purple line */

/* Model-answer points: two lattice points on f'(x) = m x + k. */
ta1 : [0, k];
ta2 : [1, m + k];

/* Values reused in feedback / worked solution. */
vertex_x : -k/m;                    /* where the tangent is horizontal (gradient 0) */

/* Worked solution reads f' off TWO points on the picture: the vertex (slope 0) and a
   second sample. Use x = 0 for simplicity - unless the vertex is already at x = 0
   (k = 0), in which case sample x = 1 so the two points are distinct. */
wsx2     : if k = 0 then 1 else 0;
wsslope2 : m*wsx2 + k;              /* tangent slope read off the graph at x = wsx2 */

feedbackvariables.text:
/* Read the two dragged points off the bound inputs. */
x1 : ans1[1];  y1 : ans1[2];
x2 : ans2[1];  y2 : ans2[2];
dx : x2 - x1;
/* Slope and intercept of the student's line, guarded against a vertical pair
   (that degenerate case is caught first, at node 0). */
sslope : if abs(dx) > 0.001 then (y2 - y1)/dx else 0;
sint   : if abs(dx) > 0.001 then y1 - sslope*x1 else 0;
/* Height of the student's line directly above the parabola's vertex - used to catch a
   line drawn THROUGH the vertex point instead of through (vertex, 0) on the x-axis. */
lineAtVertex : sslope*vertex_x + sint;
